"""Original geometry + genuine SSBH native resources, generated by the pinned writer."""
from pathlib import Path
import sys
sys.path.insert(0, str(Path(__file__).resolve().parent.parent / '.deps/ssbh-python'))
import numpy as np
import ssbh_data_py as ssbh

folder = Path(sys.argv[1]).resolve()
folder.mkdir(parents=True, exist_ok=False)
skel = ssbh.skel_data.SkelData()
root = np.eye(4, dtype=np.float32); child = root.copy(); child[3, 1] = 2
skel.bones = [ssbh.skel_data.BoneData('OriginalRoot', root), ssbh.skel_data.BoneData('OriginalArm', child, 0)]
skel.save(str(folder/'model.nusktb'))
mesh = ssbh.mesh_data.MeshData()
objects = []
for name, rigid in [('OriginalBody', False), ('OriginalAccessory', True)]:
    m = ssbh.mesh_data.MeshObjectData(name, 0)
    positions = np.array([[0, 2, 0], [1, 2, 0], [0, 3, 0]], dtype=np.float32)
    if rigid:
        positions[:, 1] -= 2
        m.parent_bone_name = 'OriginalArm'
    else:
        m.bone_influences = [ssbh.mesh_data.BoneInfluence('OriginalRoot', [ssbh.mesh_data.VertexWeight(i, .25) for i in range(3)]),
                             ssbh.mesh_data.BoneInfluence('OriginalArm', [ssbh.mesh_data.VertexWeight(i, .75) for i in range(3)])]
    m.positions = [ssbh.mesh_data.AttributeData('Position0', positions)]
    m.normals = [ssbh.mesh_data.AttributeData('Normal0', np.array([[0, 0, 1]]*3, dtype=np.float32))]
    m.texture_coordinates = [ssbh.mesh_data.AttributeData('map1', np.array([[0, 0], [1, 0], [0, 1]], dtype=np.float32))]
    m.vertex_indices = np.array([0, 1, 2], dtype=np.uint32)
    objects.append(m)
mesh.objects = objects
mesh.save(str(folder/'model.numshb'))
matl = ssbh.matl_data.MatlData();matl.entries = [ssbh.matl_data.MatlEntryData('OriginalNeutral', 'OriginalFixture_NotGameShader')];matl.save(str(folder/'model.numatb'))
modl = ssbh.modl_data.ModlData();modl.model_name = 'Original SSBH skin fixture';modl.skeleton_file_name = 'model.nusktb';modl.mesh_file_name = 'model.numshb';modl.material_file_names = ['model.numatb']
modl.entries = [ssbh.modl_data.ModlEntryData(m.name, 0, 'OriginalNeutral') for m in mesh.objects];modl.save(str(folder/'model.numdlb'))
anim = ssbh.anim_data.AnimData();anim.final_frame_index = 2
values = [ssbh.anim_data.Transform([1, 1, 1], [0, 0, float(np.sin(a/2)), float(np.cos(a/2))], [0, 2, 0]) for a in [0, np.pi/2, np.pi]]
anim.groups = [ssbh.anim_data.GroupData(ssbh.anim_data.GroupType.Transform, [ssbh.anim_data.NodeData('OriginalArm', [ssbh.anim_data.TrackData('Transform', values=values)])])]
anim.save(str(folder/'motion.nuanmb'))
print('PASS: generated original NUMDLB/SKEL/MESH/MATL/ANIM through ssbh_data_py')
